S=/private/tmp/claude-504/-Volumes-DAL-Zettelkasten-LLMeon/8a5849dd-c7ca-4b94-92bf-f2234cba474d/scratchpad && cat > $S/clean.py <<'EOF'
import os,re,sys
S,apply=sys.argv[1],sys.argv[2]=='apply'
dead={l.rstrip('\n')[:-3] for l in open(S+'/del.txt')}
rx=re.compile(r'^\s*(?:[-*] )?(?:\[[a-z_]+:: )?\[\[([^\]|#]+)(?:[|#][^\]]*)?\]\]')
skip=('99_Archive','30_Library/400_indexes','90_Audits','01_journals','20_Thinking','10_System','.git','.shale','.obsidian')
tot=0;skipped=[]
for r,d,fs in os.walk('.'):
    p=r[2:]
    if any(p.startswith(s) for s in skip): continue
    for f in fs:
        if not f.endswith('.md'): continue
        fp=os.path.join(r,f); t=open(fp,encoding='utf-8').read()
        lines=t.split('\n'); out=[]; n=0; inFM=False
        for i,l in enumerate(lines):
            if i==0 and l=='---': inFM=True; out.append(l); continue
            if inFM:
                if l=='---': inFM=False
                out.append(l); continue
            m=rx.match(l)
            if m and m.group(1).strip() in dead and l.count('[[')==1:
                n+=1; continue
            if any('[['+x in l for x in dead): skipped.append((fp,i+1))
            out.append(l)
        if n:
            tot+=n; print(n,fp[2:70])
            if apply: open(fp,'w',encoding='utf-8').write('\n'.join(out))
print('lines removed',tot)
print('left alone (inline/frontmatter/other):',len(skipped))
for s in skipped: print(s)
EOF
python3 $S/clean.py $S dry | tail -40
